{
  "title": "Discussion about living and working abroad in Slovakia, Austria and other EU countries",
  "topics": [
    {
      "id": "relocation-experiences",
      "title": "Personal experiences of living abroad",
      "claims": [
        {
          "text": "P1 asks if anyone lives in Bratislava or elsewhere in Slovakia and who has moved abroad",
          "evidence": [1]
        },
        {
          "text": "P2 mentions two acquaintances abroad: @AndriiRaccoon in Austria and walternet134 in Poland",
          "evidence": [3]
        },
        {
          "text": "P3 says they have at least two acquaintances in Austria, one recently arrived and another living there for several years",
          "evidence": [12, 13]
        },
        {
          "text": "P3 lives in Austria since 17.11.2025 and has been there for over a year",
          "evidence": [49, 54]
        },
        {
          "text": "P3's partner has lived in Austria for more than 10 years and is not optimistic about the country's future",
          "evidence": [60]
        }
      ]
    },
    {
      "id": "job-search-abroad",
      "title": "Finding jobs abroad and interview experiences",
      "claims": [
        {
          "text": "P1 asks how to find a job abroad and whether it is difficult",
          "evidence": [16]
        },
        {
          "text": "P3 says finding a job was hard but managed within two months",
          "evidence": [17]
        },
        {
          "text": "P3 recommends searching on LinkedIn",
          "evidence": [18]
        },
        {
          "text": "P3 sent about 100 applications, got 3 interviews, and attended one interview for a mid‑level position without commercial experience",
          "evidence": [21, 28]
        },
        {
          "text": "P3 notes many jobs require local language proficiency (95% mention it)",
          "evidence": [26]
        },
        {
          "text": "P3 reports that some companies still hire candidates with little language skill",
          "evidence": [29]
        },
        {
          "text": "P3 says salary for their position was higher than expected, but they accepted the minimum after stating they just needed a job",
          "evidence": [37]
        },
        {
          "text": "P3 needed to find a job before 04.03 and therefore accepted the offer",
          "evidence": [39]
        }
      ]
    },
    {
      "id": "language-requirements",
      "title": "Language expectations for jobs and daily life",
      "claims": [
        {
          "text": "P1 asks which language is spoken in Austria; P3 answers German but mentions they communicate in English with P1",
          "evidence": [14, 15]
        },
        {
          "text": "P1 notes they personally have been in Slovakia for almost a year and do not know the language",
          "evidence": [43]
        },
        {
          "text": "P1 states that work is in English, neighbors speak Ukrainian",
          "evidence": [44, 45]
        },
        {
          "text": "P3 says most job ads require B2 level, sometimes B1, and a certificate is usually not required",
          "evidence": [46]
        },
        {
          "text": "P3 is currently learning Slovak because of daily discomfort and feels pressured to speak English only",
          "evidence": [47]
        },
        {
          "text": "P1 feels language barrier at social events and English feels slightly cringe",
          "evidence": [51]
        },
        {
          "text": "P1 wants to improve spoken English on Discord channels",
          "evidence": [56, 57]
        }
      ]
    },
    {
      "id": "salary-discussion",
      "title": "Salary expectations and market comparison",
      "claims": [
        {
          "text": "P3 believes salaries in Europe are higher than in Ukraine but few notice",
          "evidence": [35]
        },
        {
          "text": "P3 says their salary was higher than expected but still a minimum compared to fast‑food wages",
          "evidence": [37]
        }
      ]
    }
  ],
  "decisions": [],
  "openQuestions": [
    {
      "text": "P1 asks P3 personally whether they plan to stay in Austria",
      "evidence": [58]
    },
    {
      "text": "P1 asks for people living in Bratislava or Slovakia and who has moved abroad (initial request)",
      "evidence": [1]
    }
  ]
}
